'use client';

import { useCallback, useEffect, useState } from 'react';

import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import {
    Tooltip,
    TooltipContent,
    TooltipProvider,
    TooltipTrigger,
} from '@/components/ui/tooltip';
import { cn } from '@/lib/utils';

import { COLORS, withAlpha } from '../tokens/colors';

const STACK_EASE = 'cubic-bezier(0.22, 1, 0.36, 1)';

export interface PresenceAvatarPerson {
    id: string;
    name: string;
    username?: string | null;
    avatarUrl?: string | null;
    isSelf?: boolean;
    /** Optional second line in tooltip (e.g. viewing surface). */
    subtitle?: string | null;
}

export interface PresenceAvatarStackProps {
    people: PresenceAvatarPerson[];
    maxVisible?: number;
    size?: number;
    className?: string;
    overflowTitle?: string;
}

function resolveProfileImageUrl(value?: string | null): string | undefined {
    if (!value) return undefined;
    if (value.startsWith('http') || value.startsWith('data:') || value.startsWith('blob:')) {
        return value;
    }
    if (value.startsWith('/api/proxy/')) return value;
    if (value.startsWith('/api/chat/media/')) return `/api/proxy${value}`;
    if (value.startsWith('/')) return value;
    return `/api/proxy/api/chat/media/?key=${encodeURIComponent(value)}`;
}

function personInitials(name: string): string {
    const parts = name.trim().split(/\s+/).filter(Boolean);
    if (parts.length === 0) return '?';
    if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
    return `${parts[0][0] ?? ''}${parts[parts.length - 1][0] ?? ''}`.toUpperCase();
}

interface PresenceAvatarFaceProps {
    person: PresenceAvatarPerson;
    index: number;
    size: number;
    overlap: number;
    useCompactStack: boolean;
    hoveredIndex: number | null;
    openTooltipId: string | null;
    onHover: (index: number) => void;
    onLeave: () => void;
    onTooltipOpenChange: (personId: string, open: boolean) => void;
}

function PresenceAvatarFace({
    person,
    index,
    size,
    overlap,
    useCompactStack,
    hoveredIndex,
    openTooltipId,
    onHover,
    onLeave,
    onTooltipOpenChange,
}: PresenceAvatarFaceProps) {
    const [imageFailed, setImageFailed] = useState(false);
    const imageSrc = resolveProfileImageUrl(person.avatarUrl);
    const isHovered = hoveredIndex === index;
    const isAnyHovered = hoveredIndex !== null;
    const tooltipLabel = person.subtitle?.trim() || (person.isSelf ? `${person.name} (você)` : person.name);

    useEffect(() => {
        setImageFailed(false);
    }, [imageSrc, person.id]);

    const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);
    useEffect(() => {
        const media = window.matchMedia('(prefers-reduced-motion: reduce)');
        const sync = () => setPrefersReducedMotion(media.matches);
        sync();
        media.addEventListener('change', sync);
        return () => media.removeEventListener('change', sync);
    }, []);

    let spreadX = 0;
    if (useCompactStack && isAnyHovered && hoveredIndex !== null && hoveredIndex !== index) {
        spreadX = index < hoveredIndex ? -4 : 4;
    }

    const transform =
        prefersReducedMotion || !isAnyHovered || !useCompactStack
            ? undefined
            : isHovered
              ? `translateY(-3px) scale(1.12) translateX(${spreadX}px)`
              : `scale(0.94) translateX(${spreadX}px)`;

    return (
        <Tooltip
            key={`presence-tooltip-${person.id}`}
            open={openTooltipId === person.id}
            onOpenChange={(open) => onTooltipOpenChange(person.id, open)}
        >
            <TooltipTrigger asChild>
                <button
                    type="button"
                    aria-label={tooltipLabel}
                    onMouseEnter={() => {
                        onHover(index);
                        onTooltipOpenChange(person.id, true);
                    }}
                    onMouseLeave={onLeave}
                    onFocus={() => {
                        onHover(index);
                        onTooltipOpenChange(person.id, true);
                    }}
                    onBlur={onLeave}
                    className={cn(
                        'relative block shrink-0 rounded-full transition-[transform,opacity,box-shadow] duration-200',
                        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-(--celer-blue) focus-visible:ring-offset-2 focus-visible:ring-offset-(--paper-surface)',
                    )}
                    style={{
                        width: size,
                        height: size,
                        marginLeft: index === 0 ? 0 : useCompactStack ? -overlap : 6,
                        zIndex: isHovered ? 30 : 10 - index,
                        transform,
                        opacity:
                            useCompactStack && isAnyHovered && !isHovered && !prefersReducedMotion
                                ? 0.68
                                : 1,
                        transitionTimingFunction: STACK_EASE,
                        boxShadow: isHovered
                            ? `0 6px 16px ${withAlpha(COLORS.text, 0.14)}`
                            : undefined,
                    }}
                >
                    <Avatar
                        className={cn(
                            'size-full border-2',
                            person.isSelf
                                ? 'border-(--celer-blue)'
                                : 'border-(--paper-surface)',
                        )}
                    >
                        {imageSrc && !imageFailed ? (
                            <AvatarImage
                                key={`${person.id}-${imageSrc}`}
                                src={imageSrc}
                                alt=""
                                className="object-cover"
                                onLoadingStatusChange={(status) => {
                                    if (status === 'error') setImageFailed(true);
                                }}
                            />
                        ) : null}
                        <AvatarFallback
                            className="font-satoshi text-[10px] font-bold text-(--paper-surface)"
                            style={{
                                background: person.isSelf
                                    ? `linear-gradient(145deg, ${COLORS.brandDeep}, ${COLORS.brand})`
                                    : `linear-gradient(145deg, ${withAlpha(COLORS.brandDeep, 0.92)}, ${withAlpha(COLORS.brand, 0.82)})`,
                            }}
                        >
                            {personInitials(person.name)}
                        </AvatarFallback>
                    </Avatar>
                </button>
            </TooltipTrigger>
            <TooltipContent
                side="bottom"
                sideOffset={8}
                className="font-satoshi border-border/60 bg-(--paper-surface) px-2 py-1 text-[11px] font-semibold text-foreground shadow-md"
            >
                {tooltipLabel}
            </TooltipContent>
        </Tooltip>
    );
}

function PresenceOverflowRow({ person, size }: { person: PresenceAvatarPerson; size: number }) {
    const [imageFailed, setImageFailed] = useState(false);
    const imageSrc = resolveProfileImageUrl(person.avatarUrl);
    const rowSize = Math.max(size - 2, 20);

    useEffect(() => {
        setImageFailed(false);
    }, [imageSrc, person.id]);

    return (
        <li
            className="flex min-w-0 items-center gap-2 rounded-md px-1 py-1.5"
            style={{
                background: person.isSelf ? withAlpha(COLORS.brand, 0.06) : undefined,
            }}
        >
            <Avatar
                className={cn(
                    'shrink-0 border-2',
                    person.isSelf ? 'border-(--celer-blue)' : 'border-(--paper-surface)',
                )}
                style={{ width: rowSize, height: rowSize }}
            >
                {imageSrc && !imageFailed ? (
                    <AvatarImage
                        key={`${person.id}-${imageSrc}`}
                        src={imageSrc}
                        alt=""
                        className="object-cover"
                        onLoadingStatusChange={(status) => {
                            if (status === 'error') setImageFailed(true);
                        }}
                    />
                ) : null}
                <AvatarFallback
                    className="font-satoshi text-[9px] font-bold text-(--paper-surface)"
                    style={{
                        background: person.isSelf
                            ? `linear-gradient(145deg, ${COLORS.brandDeep}, ${COLORS.brand})`
                            : `linear-gradient(145deg, ${withAlpha(COLORS.brandDeep, 0.92)}, ${withAlpha(COLORS.brand, 0.82)})`,
                    }}
                >
                    {personInitials(person.name)}
                </AvatarFallback>
            </Avatar>
            <div className="min-w-0 flex-1">
                <p
                    className="truncate font-satoshi text-[11px] font-semibold leading-tight"
                    style={{ color: COLORS.text }}
                >
                    {person.name}
                    {person.isSelf ? (
                        <span
                            className="ml-1 font-normal"
                            style={{ color: COLORS.brand }}
                        >
                            (você)
                        </span>
                    ) : null}
                </p>
                {person.username ? (
                    <p
                        className="truncate font-satoshi text-[10px] leading-tight"
                        style={{ color: COLORS.textDim }}
                    >
                        @{person.username}
                    </p>
                ) : null}
            </div>
        </li>
    );
}

interface PresenceOverflowPopoverProps {
    people: PresenceAvatarPerson[];
    overflowCount: number;
    size: number;
    overlap: number;
    useCompactStack: boolean;
    overflowTitle: string;
    onOpenChange?: (open: boolean) => void;
}

function PresenceOverflowPopover({
    people,
    overflowCount,
    size,
    overlap,
    useCompactStack,
    overflowTitle,
    onOpenChange,
}: PresenceOverflowPopoverProps) {
    return (
        <Popover onOpenChange={onOpenChange}>
            <PopoverTrigger asChild>
                <button
                    type="button"
                    aria-label={`Ver mais ${overflowCount} pessoas no quadro`}
                    className={cn(
                        'relative inline-flex shrink-0 cursor-pointer items-center justify-center rounded-full border-2 border-(--paper-surface) font-satoshi text-[9px] font-bold transition-opacity duration-200',
                        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-(--celer-blue) focus-visible:ring-offset-2 focus-visible:ring-offset-(--paper-surface)',
                    )}
                    style={{
                        width: size,
                        height: size,
                        marginLeft: useCompactStack ? -overlap : 6,
                        zIndex: 5,
                        background: withAlpha(COLORS.brand, 0.12),
                        color: COLORS.brand,
                    }}
                >
                    +{overflowCount}
                </button>
            </PopoverTrigger>
            <PopoverContent
                align="end"
                side="bottom"
                sideOffset={8}
                className="w-[min(100vw-2rem,280px)] border-border/60 bg-(--paper-surface) p-0 shadow-md"
            >
                <div
                    className="border-b px-3 py-2"
                    style={{ borderColor: withAlpha(COLORS.border, 0.45) }}
                >
                    <p
                        className="font-satoshi text-[11px] font-semibold"
                        style={{ color: COLORS.text }}
                    >
                        {overflowTitle}
                    </p>
                    <p className="font-satoshi text-[10px]" style={{ color: COLORS.textDim }}>
                        {overflowCount}{' '}
                        {overflowCount === 1 ? 'pessoa' : 'pessoas'}
                    </p>
                </div>
                <ul
                    className="max-h-60 overflow-y-auto overscroll-contain px-2 py-1.5"
                    aria-label={overflowTitle}
                >
                    {people.map((person) => (
                        <PresenceOverflowRow key={person.id} person={person} size={size} />
                    ))}
                </ul>
            </PopoverContent>
        </Popover>
    );
}

export function PresenceAvatarStack({
    people,
    maxVisible = 5,
