'use client';

import { PresenceAvatarStack } from '@/design-system';
import { collaborationViewerContextLabel } from '@/components/Collaboration/collaboration-viewing-surface';
import type { CollaborationViewer } from '@/types/collaboration';
import { cn } from '@/lib/utils';
import { Users } from 'lucide-react';

interface ResourcePresenceBarProps {
    viewers: CollaborationViewer[];
    currentUserId?: string | null;
    label?: string;
    className?: string;
    variant?: 'default' | 'compact';
}

export function ResourcePresenceBar({
    viewers = [],
    currentUserId,
    label = 'vendo esta página',
    className,
    variant = 'default',
}: ResourcePresenceBarProps) {
    const otherViewers = viewers.filter(
        (viewer) =>
            !currentUserId || String(viewer.user_id) !== String(currentUserId),
    );

    if (viewers.length === 0) return null;

    const people = viewers.map((viewer) => {
        const isSelf = Boolean(
            currentUserId && String(viewer.user_id) === String(currentUserId),
        );
        return {
            id: viewer.user_id,
            name: viewer.display_name || viewer.username,
            username: viewer.username,
            avatarUrl: viewer.profile_picture,
            isSelf,
            subtitle: collaborationViewerContextLabel(viewer, isSelf),
        };
    });

    const tooltipLabel =
        otherViewers.length === 0
            ? people.find((person) => person.isSelf)?.subtitle ?? 'Você está nesta página'
            : otherViewers.length === 1
              ? `${collaborationViewerContextLabel(otherViewers[0], false)} também está ${label}`
              : `${viewers.length} pessoas ${label}`;

    if (variant === 'compact') {
        return (
            <div
                className={cn(
                    'inline-flex items-center gap-1.5 rounded-full border border-border/50 bg-background/95 px-1.5 py-1 shadow-sm backdrop-blur-sm',
                    className,
                )}
                title={tooltipLabel}
                aria-label={tooltipLabel}
            >
                <PresenceAvatarStack
                    size={24}
                    maxVisible={4}
                    overflowTitle="Mais pessoas nesta página"
                    people={people}
                />
            </div>
        );
    }

    return (
        <div
            className={cn(
                'flex items-center gap-2.5 overflow-visible rounded-lg border border-border/60 bg-primary/5 px-2.5 py-1.5',
                className,
            )}
        >
            <Users className="size-3.5 shrink-0 text-muted-foreground" aria-hidden />
            <span className="font-satoshi text-[11px] text-muted-foreground">
                {viewers.length} {label}
            </span>
            <PresenceAvatarStack
                size={26}
                maxVisible={5}
                overflowTitle="Mais pessoas nesta página"
                people={people}
            />
        </div>
    );
}

