333	    const [cardMap, setCardMap] = useState<Record<string, DueDiligenceResumo>>({});
334	    const [updatingPriorityId, setUpdatingPriorityId] = useState<string | null>(null);
335	    const [viewers, setViewers] = useState<LiquidacaoBoardViewer[]>([]);
336	    const [cardLocks, setCardLocks] = useState<Record<string, LiquidacaoBoardCardLock>>({});
337	    const cardLocksRef = useRef<Record<string, LiquidacaoBoardCardLock>>({});
338	    const isDraggingRef = useRef(false);
