'use client';

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import type { DragEndEvent, DragStartEvent } from '@dnd-kit/core';
import { RefreshCw, LayoutGrid, Users } from 'lucide-react';
import { KanbanHorizontalScroll } from '@/app/crm/tarefas/_components/KanbanHorizontalScroll';
import {
    KanbanBoard,
    KanbanCard,
    KanbanCards,
    KanbanHeader,
    KanbanProvider,
    isSameKanbanOrder,
    type KanbanItemProps,
} from '@/components/kibo-ui/kanban';
import { QueryKeys } from '@/constants/query-keys';
import { COLORS, withAlpha } from '@/constants/celer-product-colors';
import { OperationalEmptyState, OperationalLoadingPanel, PresenceAvatarStack } from '@/design-system';
import {
    SubStatusLiquidacaoLabels,
    SubStatusLiquidacaoSemColuna,
    SubStatusLiquidacaoSemColunaLabel,
    SubStatusLiquidacaoSemColunaHint,
    DuePriorityLevel,
    DuePriorityLevelLabels,
    LiquidacaoQueueOrdering,
} from '@/enums/dueDiligence';
import {
    resolveCollaborationViewers,
} from '@/components/Collaboration/collaboration-user';
import {
    useCollaborationCurrentUserId,
    useCollaborationUserProfile,
} from '@/components/Collaboration/use-collaboration-user';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import { shouldRefetchBoardAfterRemoteEvent } from '@/functions/liquidacao-board-remote-sync';
import { sortKanbanItemsByPriority } from '@/functions/liquidacao-kanban-sort';
import {
    useLiquidacaoBoardCollaboration,
    type LiquidacaoBoardCardLock,
    type LiquidacaoBoardCardMovedEvent,
    type LiquidacaoBoardPriorityChangedEvent,
    type LiquidacaoBoardViewer,
} from '@/hooks/useLiquidacaoBoardCollaboration';
import {
    getLiquidacaoBoard,
    setDuePriority,
    updateDueSubStatus,
    type LiquidacaoBoardColumn,
    type LiquidacaoBoardResponse,
} from '@/services/due-diligence';
import type { Filter } from '@/types/filter';
import type { DueDiligenceResumo } from '@/types/due-diligence';
import { cn } from '@/lib/utils';
import {
    LiquidacaoKanbanCard,
    resolveKanbanCardPriority,
} from './LiquidacaoKanbanCard';
import { ColumnHeatSummary } from './ColumnHeatSummary';

/** Largura fixa das colunas — cards de liquidação têm prazo + SLA + pessoas. */
const LIQUIDACAO_KANBAN_COLUMN_CLASS = 'w-[320px] min-w-[320px] max-w-[320px] shrink-0';

function normalizeBoardViewer(viewer: LiquidacaoBoardViewer): LiquidacaoBoardViewer {
    return {
        ...viewer,
        user_id: String(viewer.user_id),
        display_name: viewer.display_name?.trim() || viewer.username?.trim() || 'Usuário',
    };
}

function boardViewersSignature(viewers: LiquidacaoBoardViewer[]): string {
    return viewers
        .map(
            (viewer) =>
                `${viewer.user_id}:${viewer.display_name}:${viewer.profile_picture ?? ''}:${viewer.username ?? ''}`,
        )
        .sort()
        .join('|');
}

function sortBoardViewers(
    viewers: LiquidacaoBoardViewer[],
    currentUserId?: string | null,
): LiquidacaoBoardViewer[] {
    const normalized = viewers.map(normalizeBoardViewer);
    return [...normalized].sort((left, right) => {
        if (currentUserId) {
            if (left.user_id === currentUserId && right.user_id !== currentUserId) return -1;
            if (right.user_id === currentUserId && left.user_id !== currentUserId) return 1;
        }
        return left.display_name.localeCompare(right.display_name, 'pt-BR', {
            sensitivity: 'base',
        });
    });
}

interface LiquidacaoKanbanViewProps {
    filters: Filter[];
    currentUsername?: string;
    ordering?: LiquidacaoQueueOrdering;
}

function boardToKanbanItems(columns: LiquidacaoBoardColumn[]): KanbanItemProps[] {
    return columns.flatMap((column) =>
        column.cards.map((card) => ({
            id: String(card.id),
            name: card.credor,
            column: column.id,
        })),
    );
}

function buildBoardSyncKey(columns: LiquidacaoBoardColumn[]): string {
    return JSON.stringify(
        columns.map((column) => ({
            id: column.id,
            cards: column.cards.map((card) => ({
                id: String(card.id),
                sub_status: card.sub_status,
                priority_level: card.priority_level,
                is_priority: card.is_priority,
            })),
        })),
    );
}

function buildCardMapFromColumns(columns: LiquidacaoBoardColumn[]): Record<string, DueDiligenceResumo> {
    const map: Record<string, DueDiligenceResumo> = {};
    columns.forEach((column) => {
        column.cards.forEach((card) => {
            map[String(card.id)] = card;
        });
    });
    return map;
}

function resolveColumnIdFromSubStatus(subStatus: string | null): string {
    if (subStatus === null) return SubStatusLiquidacaoSemColuna;
    return subStatus;
}

function resolveSubStatusFromColumn(columnId: string): string | null {
    if (columnId === SubStatusLiquidacaoSemColuna) return null;
    return columnId;
}

function resolveColumnLabel(columnId: string): string {
    if (columnId === SubStatusLiquidacaoSemColuna) return SubStatusLiquidacaoSemColunaLabel;
    return SubStatusLiquidacaoLabels[columnId as keyof typeof SubStatusLiquidacaoLabels] ?? columnId;
}

function firstNameFromDisplay(label: string): string {
    const trimmed = label.trim();
    if (!trimmed) return 'Usuário';
    return trimmed.split(/\s+/)[0] ?? trimmed;
}

function patchBoardQueryAfterMove(
    board: LiquidacaoBoardResponse | undefined,
    dueId: string,
    targetColumn: string,
    subStatus: string | null,
): LiquidacaoBoardResponse | undefined {
    if (!board?.columns) return board;

    let movedCard: DueDiligenceResumo | null = null;
    const columnsWithoutCard = board.columns.map((column) => ({
        ...column,
        cards: column.cards.filter((card) => {
            if (String(card.id) !== String(dueId)) return true;
            movedCard = {
                ...card,
                sub_status: subStatus,
                sub_status_display: resolveColumnLabel(targetColumn),
            };
            return false;
        }),
    }));

    if (!movedCard) return board;

    return {
        ...board,
        columns: columnsWithoutCard.map((column) =>
            column.id === targetColumn
                ? { ...column, cards: [...column.cards, movedCard!] }
                : column,
        ),
    };
}

function patchBoardQueryAfterPriority(
    board: LiquidacaoBoardResponse | undefined,
    dueId: string,
    priorityLevel: DuePriorityLevel | null,
    isPriority: boolean,
): LiquidacaoBoardResponse | undefined {
    if (!board?.columns) return board;

    return {
        ...board,
        columns: board.columns.map((column) => ({
            ...column,
            cards: column.cards.map((card) =>
                String(card.id) === String(dueId)
                    ? {
                          ...card,
                          priority_level: priorityLevel,
                          is_priority: isPriority,
                          priority_level_display: priorityLevel
                              ? DuePriorityLevelLabels[priorityLevel]
                              : null,
                      }
                    : card,
            ),
        })),
    };
}

function LiquidacaoBoardLiveIndicator({ isConnected }: { isConnected: boolean }) {
    return (
        <span
            className="inline-flex items-center gap-1.5 rounded-lg border px-2.5 py-1.5 font-satoshi text-[11px] font-medium"
            style={{
                borderColor: withAlpha(COLORS.border, 0.55),
                color: isConnected ? COLORS.textDim : COLORS.textMuted,
            }}
            title={isConnected ? 'Sincronização em tempo real ativa' : 'Reconectando ao quadro…'}
        >
            <span
                className={cn('size-2 shrink-0 rounded-full', isConnected && 'animate-pulse')}
                style={{
                    background: isConnected ? COLORS.success : withAlpha(COLORS.textMuted, 0.5),
                }}
                aria-hidden
            />
            {isConnected ? 'Ao vivo' : 'Reconectando…'}
        </span>
    );
}

function LiquidacaoBoardPresenceBar({
    viewers,
    currentUserId,
}: {
    viewers: LiquidacaoBoardViewer[];
    currentUserId?: string | null;
}) {
    if (viewers.length === 0) return null;

    return (
        <div
            className="flex items-center gap-2.5 overflow-visible rounded-lg border px-2.5 py-1.5"
            style={{
                borderColor: withAlpha(COLORS.border, 0.55),
                background: withAlpha(COLORS.brand, 0.04),
            }}
        >
            <Users className="size-3.5 shrink-0" style={{ color: COLORS.textDim }} />
            <span className="font-satoshi text-[11px]" style={{ color: COLORS.textDim }}>
                {viewers.length} vendo o quadro
            </span>
            <PresenceAvatarStack
                size={26}
                maxVisible={5}
                overflowTitle="Mais pessoas vendo o quadro"
                people={viewers.map((viewer) => ({
                    id: viewer.user_id,
                    name: viewer.display_name || viewer.username,
                    username: viewer.username,
                    avatarUrl: viewer.profile_picture,
                    isSelf: Boolean(
                        currentUserId && String(viewer.user_id) === String(currentUserId),
                    ),
                }))}
            />
        </div>
    );
}

function normalizeBoardColumns(apiColumns: LiquidacaoBoardColumn[]): { id: string; name: string }[] {
    const cols = apiColumns.map((col) => ({ id: col.id, name: col.name }));
    const semIndex = cols.findIndex((col) => col.id === SubStatusLiquidacaoSemColuna);

    if (semIndex === -1) {
        return [{ id: SubStatusLiquidacaoSemColuna, name: SubStatusLiquidacaoSemColunaLabel }, ...cols];
    }

    if (semIndex === 0) return cols;

    const semColumn = cols[semIndex];
    return [semColumn, ...cols.filter((_, index) => index !== semIndex)];
}

export function LiquidacaoKanbanView({
    filters,
    currentUsername,
    ordering = LiquidacaoQueueOrdering.FILA,
}: LiquidacaoKanbanViewProps) {
    const queryClient = useQueryClient();
    const currentUserId = useCollaborationCurrentUserId();
    const userProfile = useCollaborationUserProfile();
    const filterKey = useMemo(() => JSON.stringify({ filters, ordering }), [filters, ordering]);

    const { data, isLoading, isFetching, refetch } = useQuery({
        queryKey: [QueryKeys.juridico.liquidationBoard, filterKey, currentUsername],
        queryFn: () => getLiquidacaoBoard(filters, currentUsername, ordering),
        staleTime: 30_000,
        placeholderData: (prev) => prev,
    });

    const columns = useMemo(() => {
        if (data?.columns?.length) {
            return normalizeBoardColumns(data.columns);
        }
        return [{ id: SubStatusLiquidacaoSemColuna, name: SubStatusLiquidacaoSemColunaLabel }];
    }, [data?.columns]);

    const columnHeatById = useMemo(() => {
        const map: Record<string, LiquidacaoBoardColumn['heat_summary']> = {};
        data?.columns?.forEach((column) => {
            if (column.heat_summary) {
                map[column.id] = column.heat_summary;
            }
        });
        return map;
    }, [data?.columns]);

    const [kanbanData, setKanbanData] = useState<KanbanItemProps[]>([]);
    const kanbanDataRef = useRef<KanbanItemProps[]>([]);
    const [cardMap, setCardMap] = useState<Record<string, DueDiligenceResumo>>({});
    const [updatingPriorityId, setUpdatingPriorityId] = useState<string | null>(null);
    const [viewers, setViewers] = useState<LiquidacaoBoardViewer[]>([]);
    const [cardLocks, setCardLocks] = useState<Record<string, LiquidacaoBoardCardLock>>({});
    const cardLocksRef = useRef<Record<string, LiquidacaoBoardCardLock>>({});
    const isDraggingRef = useRef(false);
    const dragStartColumnRef = useRef<Record<string, string>>({});
    const preDragSnapshotRef = useRef<KanbanItemProps[] | null>(null);
    const activeDragDueIdRef = useRef<string | null>(null);
    const [activeDragDueId, setActiveDragDueId] = useState<string | null>(null);
    const lastBoardSyncKeyRef = useRef('');
    const boardSyncedRef = useRef(false);
    const cardMapRef = useRef(cardMap);
    const filtersRef = useRef(filters);

    cardMapRef.current = cardMap;
    filtersRef.current = filters;

    useEffect(() => {
        cardLocksRef.current = cardLocks;
    }, [cardLocks]);

    const boardSyncKey = useMemo(() => {
        if (!data?.columns) return '';
        return buildBoardSyncKey(data.columns);
    }, [data?.columns]);

    useEffect(() => {
        if (!data?.columns || isDraggingRef.current) return;
        if (lastBoardSyncKeyRef.current === boardSyncKey) return;

        const items = boardToKanbanItems(data.columns);
        lastBoardSyncKeyRef.current = boardSyncKey;
        boardSyncedRef.current = true;
        setKanbanData(items);
        kanbanDataRef.current = items;
        setCardMap(buildCardMapFromColumns(data.columns));
    }, [boardSyncKey, data?.columns]);

    const syncKanbanFromBoardColumns = useCallback((columns: LiquidacaoBoardColumn[]) => {
        const items = boardToKanbanItems(columns);
        lastBoardSyncKeyRef.current = buildBoardSyncKey(columns);
        boardSyncedRef.current = true;
        kanbanDataRef.current = items;
        setKanbanData(items);
        setCardMap(buildCardMapFromColumns(columns));
    }, []);

    const applySortedKanbanState = useCallback(
        (nextCardMap: Record<string, DueDiligenceResumo>) => {
            setCardMap(nextCardMap);
            setKanbanData((prev) => {
                const sorted = sortKanbanItemsByPriority(prev, nextCardMap, ordering);
                if (isSameKanbanOrder(prev, sorted)) return prev;
                kanbanDataRef.current = sorted;
                return sorted;
            });
        },
        [],
    );

    const revertDragSnapshot = useCallback(() => {
        const snapshot = preDragSnapshotRef.current;
        if (!snapshot) return;
        kanbanDataRef.current = snapshot;
        setKanbanData(snapshot);
        preDragSnapshotRef.current = null;
    }, []);

    const upsertCardLock = useCallback((lock: LiquidacaoBoardCardLock) => {
        setCardLocks((prev) => ({ ...prev, [String(lock.due_id)]: lock }));
    }, []);

    const removeCardLock = useCallback((dueId: string) => {
        setCardLocks((prev) => {
            const key = String(dueId);
            if (!prev[key]) return prev;
            const next = { ...prev };
            delete next[key];
            return next;
        });
    }, []);

    const boardQueryKey = useMemo(
        () => [QueryKeys.juridico.liquidationBoard, filterKey, currentUsername] as const,
        [filterKey, currentUsername],
    );

    const applyRemoteCardMove = useCallback(
        (event: LiquidacaoBoardCardMovedEvent) => {
            if (
                isDraggingRef.current &&
                activeDragDueIdRef.current &&
                String(activeDragDueIdRef.current) === String(event.due_id)
            ) {
                return;
            }

            if (
                currentUserId &&
                event.actor_user_id &&
                String(event.actor_user_id) === String(currentUserId)
            ) {
                return;
            }

            removeCardLock(event.due_id);

            const dueId = String(event.due_id);
            const targetColumn = event.to_column;
            const actorLabel = firstNameFromDisplay(
                event.actor_username || 'Outro usuário',
            );

            if (
                shouldRefetchBoardAfterRemoteEvent(
                    dueId,
                    cardMapRef.current,
                    filtersRef.current,
                    'move',
                    { boardSynced: boardSyncedRef.current },
                )
            ) {
                void refetch();
                sendToastMessage({
                    type: 'info',
                    title: `${actorLabel} moveu ${event.credor ?? 'uma operação'} para ${resolveColumnLabel(targetColumn)}`,
                });
                return;
            }

            let patchedBoard: LiquidacaoBoardResponse | undefined;
            queryClient.setQueryData<LiquidacaoBoardResponse>(boardQueryKey, (old) => {
                patchedBoard = patchBoardQueryAfterMove(old, dueId, targetColumn, event.sub_status);
                return patchedBoard;
            });

            if (patchedBoard?.columns) {
                syncKanbanFromBoardColumns(patchedBoard.columns);
            } else {
                setKanbanData((prev) => {
                    const current = prev.find((entry) => String(entry.id) === dueId);
                    if (!current || current.column === targetColumn) return prev;
                    const next = prev.map((entry) =>
                        String(entry.id) === dueId ? { ...entry, column: targetColumn } : entry,
                    );
                    kanbanDataRef.current = next;
                    return next;
                });

                setCardMap((prev) => {
                    const card = prev[dueId];
                    if (!card) return prev;
                    return {
                        ...prev,
                        [dueId]: {
                            ...card,
                            sub_status: event.sub_status,
                            sub_status_display: resolveColumnLabel(targetColumn),
                        },
                    };
                });
            }

            sendToastMessage({
                type: 'info',
                title: `${actorLabel} moveu ${event.credor ?? 'uma operação'} para ${resolveColumnLabel(targetColumn)}`,
            });
        },
        [
            boardQueryKey,
            currentUserId,
            queryClient,
            refetch,
            removeCardLock,
            syncKanbanFromBoardColumns,
        ],
    );

    const applyRemotePriorityChange = useCallback(
        (event: LiquidacaoBoardPriorityChangedEvent) => {
            if (isDraggingRef.current) return;

            const dueId = String(event.due_id);
            const level = event.priority_level as DuePriorityLevel | null;
            const actorLabel = firstNameFromDisplay(event.actor_username || 'Outro usuário');

            if (
                shouldRefetchBoardAfterRemoteEvent(
                    dueId,
                    cardMapRef.current,
                    filtersRef.current,
                    'priority',
                    { boardSynced: boardSyncedRef.current },
                )
            ) {
                void refetch();
                const card = cardMapRef.current[dueId];
                const priorityLabel = level ? DuePriorityLevelLabels[level] : 'removida';
                sendToastMessage({
                    type: 'info',
                    title: `${actorLabel} alterou prioridade de ${card?.credor ?? 'uma operação'} para ${priorityLabel}`,
                });
                return;
            }

            let patchedBoard: LiquidacaoBoardResponse | undefined;
            queryClient.setQueryData<LiquidacaoBoardResponse>(boardQueryKey, (old) => {
                patchedBoard = patchBoardQueryAfterPriority(
                    old,
                    dueId,
                    level,
                    event.is_priority,
                );
                return patchedBoard;
            });

            const patchedCard = patchedBoard?.columns
                ?.flatMap((column) => column.cards)
                .find((entry) => String(entry.id) === dueId);
            const card = patchedCard ?? cardMapRef.current[dueId];
            if (!card) return;

            applySortedKanbanState({
                ...cardMapRef.current,
                [dueId]: {
                    ...card,
                    priority_level: level,
                    is_priority: event.is_priority,
                    priority_level_display: level ? DuePriorityLevelLabels[level] : null,
                },
            });

            const priorityLabel = level ? DuePriorityLevelLabels[level] : 'removida';
            sendToastMessage({
                type: 'info',
                title: `${actorLabel} alterou prioridade de ${card.credor ?? 'uma operação'} para ${priorityLabel}`,
            });
        },
        [applySortedKanbanState, boardQueryKey, queryClient, refetch],
    );

    const handleViewersSnapshot = useCallback(
        (nextViewers: LiquidacaoBoardViewer[]) => {
            setViewers((prev) => {
                const normalized = sortBoardViewers(nextViewers, currentUserId);
                if (boardViewersSignature(prev) === boardViewersSignature(normalized)) {
                    return prev;
                }
                return normalized;
            });
        },
        [currentUserId],
    );

    const handleLocksSnapshot = useCallback((locks: LiquidacaoBoardCardLock[]) => {
        const next: Record<string, LiquidacaoBoardCardLock> = {};
        locks.forEach((lock) => {
            next[String(lock.due_id)] = lock;
        });
        setCardLocks((prev) => {
            const prevKeys = Object.keys(prev);
            const nextKeys = Object.keys(next);
            if (
                prevKeys.length === nextKeys.length &&
                prevKeys.every(
                    (key) =>
                        prev[key]?.user_id === next[key]?.user_id &&
                        prev[key]?.display_name === next[key]?.display_name,
                )
            ) {
                return prev;
            }
            return next;
        });
    }, []);

    const applyRemoteSlaConfigChange = useCallback(
        (event: { actor_user_id?: string; actor_username?: string }) => {
            void refetch();

            if (
                currentUserId &&
                event.actor_user_id &&
                String(event.actor_user_id) !== String(currentUserId)
            ) {
                const actorLabel = firstNameFromDisplay(event.actor_username || 'Operação');
                sendToastMessage({
                    type: 'info',
                    title: `${actorLabel} atualizou metas SLA. Quadro recarregado.`,
                });
            }
        },
        [currentUserId, refetch],
    );

    const { acquireCardLock, releaseCardLock, isConnected } = useLiquidacaoBoardCollaboration({
        enabled: Boolean(currentUserId),
        currentUserId,
        activeDragDueId,
        onViewers: handleViewersSnapshot,
        onViewerJoined: (viewer) => {
            const normalized = normalizeBoardViewer(viewer);
            setViewers((prev) => {
                const index = prev.findIndex((entry) => entry.user_id === normalized.user_id);
                const merged =
                    index === -1
                        ? [...prev, normalized]
                        : prev.map((entry, entryIndex) =>
                              entryIndex === index ? normalized : entry,
                          );
                return sortBoardViewers(merged, currentUserId);
            });
        },
        onViewerLeft: (userId) => {
            setViewers((prev) => prev.filter((entry) => entry.user_id !== String(userId)));
        },
        onLocksSnapshot: handleLocksSnapshot,
        onCardLocked: upsertCardLock,
        onCardUnlocked: (dueId) => {
            removeCardLock(dueId);
        },
        onCardMoved: applyRemoteCardMove,
        onPriorityChanged: applyRemotePriorityChange,
        onSlaConfigChanged: applyRemoteSlaConfigChange,
        onDueStateChanged: () => {
            void refetch();
        },
    });

    const displayViewers = useMemo(
        () =>
            sortBoardViewers(
                resolveCollaborationViewers(viewers, userProfile, isConnected) as LiquidacaoBoardViewer[],
                currentUserId,
            ),
        [currentUserId, isConnected, userProfile, viewers],
    );

    const releaseActiveDragLock = useCallback(() => {
        const dueId = activeDragDueIdRef.current;
        if (dueId) {
            releaseCardLock(dueId);
            activeDragDueIdRef.current = null;
            setActiveDragDueId(null);
        }
    }, [releaseCardLock]);

    const handlePriorityChange = useCallback(
        async (dueId: string, level: DuePriorityLevel | null) => {
            const previousCard = cardMap[dueId];
            if (!previousCard) return;

            const snapshot = cardMap;
            const optimisticCard: DueDiligenceResumo = {
                ...previousCard,
                priority_level: level,
                is_priority: level === DuePriorityLevel.ALTA,
                priority_level_display: level ? DuePriorityLevelLabels[level] : null,
            };

            applySortedKanbanState({ ...snapshot, [dueId]: optimisticCard });
            setUpdatingPriorityId(dueId);

            try {
                await setDuePriority(dueId, level);
                queryClient.setQueryData<LiquidacaoBoardResponse>(boardQueryKey, (old) =>
                    patchBoardQueryAfterPriority(
                        old,
                        dueId,
                        level,
                        level === DuePriorityLevel.ALTA,
                    ),
                );
                sendToastMessage({
                    type: 'success',
                    title: level
                        ? `Prioridade ${DuePriorityLevelLabels[level]} aplicada`
                        : 'Prioridade removida',
                });
                await queryClient.invalidateQueries({ queryKey: [QueryKeys.juridico.liquidation] });
                await queryClient.invalidateQueries({
                    queryKey: [QueryKeys.dueDiligence.liquidationCounts],
                });
            } catch {
                applySortedKanbanState(snapshot);
                sendToastMessage({ type: 'error', title: 'Erro ao alterar prioridade.' });
            } finally {
                setUpdatingPriorityId(null);
            }
        },
        [applySortedKanbanState, boardQueryKey, cardMap, queryClient],
    );

    const moveMutation = useMutation({
        mutationFn: async ({ dueId, subStatus }: { dueId: string; subStatus: string | null }) =>
            updateDueSubStatus(dueId, subStatus),
        onSuccess: (_response, variables) => {
            const targetColumn = resolveColumnIdFromSubStatus(variables.subStatus);
            queryClient.setQueryData<LiquidacaoBoardResponse>(boardQueryKey, (old) =>
                patchBoardQueryAfterMove(
                    old,
                    String(variables.dueId),
                    targetColumn,
                    variables.subStatus,
                ),
            );
            queryClient.invalidateQueries({ queryKey: [QueryKeys.juridico.liquidation] });
            queryClient.invalidateQueries({ queryKey: [QueryKeys.dueDiligence.liquidationCounts] });
            queryClient.invalidateQueries({ queryKey: [QueryKeys.dueDiligence.listSummary] });
            queryClient.invalidateQueries({ queryKey: [QueryKeys.dueDiligence.liquidacaoDashboard] });
        },
        onError: (error: unknown) => {
            const detail =
                typeof error === 'object' &&
                error !== null &&
                'response' in error &&
                typeof (error as { response?: { data?: { detail?: unknown } } }).response?.data
                    ?.detail === 'string'
                    ? ((error as { response: { data: { detail: string } } }).response.data.detail)
                    : null;
            sendToastMessage({
                type: 'error',
                title: detail ?? 'Não foi possível mover o card no quadro',
            });
            refetch();
        },
    });

    const handleDataChange = useCallback((nextData: KanbanItemProps[]) => {
        if (isSameKanbanOrder(kanbanDataRef.current, nextData)) return;
        kanbanDataRef.current = nextData;
        setKanbanData(nextData);
    }, []);

    const handleDragStart = useCallback(
        (event: DragStartEvent) => {
            const activeId = String(event.active.id);
            preDragSnapshotRef.current = [...kanbanDataRef.current];

            const remoteLock = cardLocksRef.current[activeId];
            if (remoteLock && String(remoteLock.user_id) !== String(currentUserId)) {
                sendToastMessage({
                    type: 'info',
                    title: `${firstNameFromDisplay(remoteLock.display_name || remoteLock.username)} está movendo este card`,
                });
                revertDragSnapshot();
                return;
            }

            isDraggingRef.current = true;
            activeDragDueIdRef.current = activeId;
            setActiveDragDueId(activeId);
            const item = kanbanDataRef.current.find((entry) => entry.id === activeId);
            if (item) {
                dragStartColumnRef.current[activeId] = item.column;
            }

            void acquireCardLock(activeId).then((result) => {
                if (!result.ok) {
                    isDraggingRef.current = false;
                    activeDragDueIdRef.current = null;
                    setActiveDragDueId(null);
                    if (result.lock) {
                        upsertCardLock(result.lock);
                        sendToastMessage({
                            type: 'info',
                            title: `${firstNameFromDisplay(result.lock.display_name || result.lock.username)} está movendo este card`,
                        });
                    }
                    revertDragSnapshot();
                    releaseCardLock(activeId);
                    return;
                }

                if (result.lock) {
                    upsertCardLock(result.lock);
                }
            });
        },
        [
            acquireCardLock,
            currentUserId,
            releaseCardLock,
            revertDragSnapshot,
            upsertCardLock,
        ],
    );

    const finalizeDrag = useCallback(() => {
        isDraggingRef.current = false;
        preDragSnapshotRef.current = null;
        releaseActiveDragLock();
    }, [releaseActiveDragLock]);

    const handleDragEnd = useCallback(
        (_event: DragEndEvent) => {
            const nextData = kanbanDataRef.current;

            for (const item of nextData) {
                const previousColumn = dragStartColumnRef.current[String(item.id)];
                if (!previousColumn || previousColumn === item.column) continue;

                const subStatus = resolveSubStatusFromColumn(item.column);
                moveMutation.mutate({ dueId: String(item.id), subStatus });
                delete dragStartColumnRef.current[String(item.id)];
            }

            finalizeDrag();
        },
        [finalizeDrag, moveMutation],
    );

    const handleDragCancel = useCallback(() => {
        revertDragSnapshot();
        finalizeDrag();
    }, [finalizeDrag, revertDragSnapshot]);

    if (isLoading && !data) {
        return (
            <OperationalLoadingPanel
                minHeight="480px"
                message="Montando quadro de liquidação…"
            />
        );
    }

    const total = data?.total ?? 0;

    return (
        <div className="min-w-0 space-y-3">
            <div className="flex min-w-0 flex-wrap items-center justify-between gap-3">
                <p className="min-w-0 flex-1 font-satoshi text-xs" style={{ color: COLORS.textDim }}>
                    {total} operação{total !== 1 ? 'ões' : ''} no quadro · arraste para mudar o sub-status ·
                    atualizações em tempo real
                </p>
                <div className="flex shrink-0 flex-wrap items-center gap-2">
                    <LiquidacaoBoardLiveIndicator isConnected={isConnected} />
                    <LiquidacaoBoardPresenceBar viewers={displayViewers} currentUserId={currentUserId} />
                    <button
                    type="button"
                    onClick={() => refetch()}
                    className="inline-flex cursor-pointer items-center gap-1.5 rounded-lg border px-2.5 py-1.5 text-xs font-semibold transition-colors hover:opacity-90"
                    style={{ borderColor: COLORS.border, color: COLORS.text }}
                >
                    <RefreshCw className={cn('size-3.5', isFetching && 'animate-spin')} />
                    Atualizar quadro
                </button>
                </div>
            </div>

            {total === 0 ? (
                <div
                    className="overflow-hidden rounded-2xl border"
                    style={{ borderColor: COLORS.border, background: COLORS.card }}
                >
                    <OperationalEmptyState
                        icon={LayoutGrid}
                        title="Nenhuma operação no quadro"
                        description="Ajuste os filtros ou aguarde novas diligências entrarem em liquidação ou cessão."
                        className="min-h-64"
                    />
                </div>
            ) : (
                <KanbanHorizontalScroll>
                    <KanbanProvider
                        columns={columns}
                        data={kanbanData}
                        onDataChange={handleDataChange}
                        onDragStart={handleDragStart}
                        onDragEnd={handleDragEnd}
                        onDragCancel={handleDragCancel}
                        className="min-h-[480px] auto-cols-[320px] grid-flow-col gap-3 pb-2"
                    >
                        {(column) => {
                            const isSemSubStatus = column.id === SubStatusLiquidacaoSemColuna;
                            return (
                            <KanbanBoard
                                key={column.id}
                                id={column.id}
                                className={cn(
                                    LIQUIDACAO_KANBAN_COLUMN_CLASS,
                                    'flex h-[min(72vh,640px)] flex-col overflow-hidden rounded-xl border border-border/50 bg-(--paper-surface) shadow-none',
                                )}
                            >
                                <KanbanHeader
                                    className="font-satoshi flex shrink-0 items-center justify-between gap-1.5 border-b px-3 py-2.5"
                                    style={{
                                        borderColor: withAlpha(
                                            isSemSubStatus ? COLORS.warning : COLORS.border,
                                            isSemSubStatus ? 0.55 : 0.45,
                                        ),
                                        color: COLORS.text,
                                        background: isSemSubStatus
                                            ? withAlpha(COLORS.warning, 0.08)
                                            : undefined,
                                    }}
                                >
                                    <span
                                        className="truncate text-xs font-semibold"
                                        title={isSemSubStatus ? SubStatusLiquidacaoSemColunaHint : undefined}
                                    >
                                        {column.name}
                                    </span>
                                    <span
                                        className="rounded-full px-2 py-0.5 text-[10px] font-bold"
                                        style={{
                                            background: withAlpha(COLORS.brand, 0.12),
                                            color: COLORS.brand,
                                        }}
                                    >
                                        {kanbanData.filter((item) => item.column === column.id).length}
                                    </span>
                                </KanbanHeader>
                                <ColumnHeatSummary summary={columnHeatById[column.id]} />
                                <KanbanCards id={column.id} className="gap-2">
                                    {(item) => {
                                        const resumo = cardMap[item.id];
                                        if (!resumo) return null;
                                        const priorityLevel = resolveKanbanCardPriority(resumo);
                                        const cardLock = cardLocks[String(item.id)];
                                        const lockedByOther =
                                            Boolean(cardLock) &&
                                            String(cardLock.user_id) !== String(currentUserId);
                                        const lockHolderName = lockedByOther
                                            ? firstNameFromDisplay(
                                                  cardLock.display_name || cardLock.username,
                                              )
                                            : null;
                                        const lockHolderAvatarUrl = lockedByOther
                                            ? cardLock.profile_picture
                                            : null;
                                        return (
                                            <KanbanCard
                                                key={item.id}
                                                id={item.id}
                                                name={item.name}
                                                column={item.column}
                                                useDragHandle
                                                dragDisabled={lockedByOther}
                                                className={cn(
                                                    'w-full max-w-full gap-2.5 border bg-(--paper-surface) p-3 shadow-sm transition-shadow duration-200',
                                                    lockedByOther && 'opacity-80',
                                                    priorityLevel === DuePriorityLevel.ALTA &&
                                                        'border-orange-300/70 shadow-orange-100/80',
                                                    priorityLevel === DuePriorityLevel.MEDIA &&
                                                        'border-amber-200/80',
                                                    !priorityLevel && !lockedByOther && 'border-border/60',
                                                    lockedByOther && 'border-dashed',
                                                )}
                                            >
                                                <LiquidacaoKanbanCard
                                                    resumo={resumo}
                                                    priorityLevel={priorityLevel}
                                                    lockHolderName={lockHolderName}
                                                    lockHolderAvatarUrl={lockHolderAvatarUrl}
                                                    isPriorityUpdating={
                                                        updatingPriorityId === String(resumo.id)
                                                    }
                                                    onPriorityChange={(level) =>
                                                        handlePriorityChange(String(resumo.id), level)
                                                    }
                                                />
                                            </KanbanCard>
                                        );
                                    }}
                                </KanbanCards>
                            </KanbanBoard>
                            );
                        }}
                    </KanbanProvider>
                </KanbanHorizontalScroll>
            )}
        </div>
    );
}

