'use client';

import { KanbanHorizontalScroll } from '@/app/crm/tarefas/_components/KanbanHorizontalScroll';
import { ColumnHeatSummary } from '@/components/Juridico/ColumnHeatSummary';
import {
    COLORS,
    OperationalEmptyState,
    OperationalLoadingPanel,
    PresenceAvatarStack,
    withAlpha,
} from '@/design-system';
import type { LiquidacaoBoardViewer } from '@/hooks/useLiquidacaoBoardCollaboration';
import { cn } from '@/lib/utils';
import { useDueDiligenceStore } from '@/store/useDueDiligenceStore';
import { LayoutGrid, RefreshCw, Users } from 'lucide-react';
import dynamic from 'next/dynamic';
import type {
    ILiquidacaoCardKanban,
    ILiquidacaoSubstatusKanbanCardViewModel,
} from '../../interfaces/liquidacaoKanban';
import type { ILiqKanbanCardResponsaveisSnapshot } from '../../interfaces/store';
import { substatusKanbanService } from '../../services/SubstatusKanbanService';
import { buildKanbanCardResponsaveisPresentation } from '../../utils/DueLiquidacao/buildKanbanCardResponsaveisPresentation';
import { resolveLiquidacaoDedicatedHref } from '../../utils/DueLiquidacao/resolveLiquidacaoDedicatedHref';
import {
    useViewModelSubstatusKanban,
    type ISubstatusKanbanBoardColumnView,
} from '../../ViewModels/useViewModelSubstatusKanban';
import { LiquidacaoSubstatusKanbanCard } from './LiquidacaoSubstatusKanbanCard';

const SUBSTATUS_KANBAN_COLUMN_CLASS = 'w-[320px] min-w-[320px] max-w-[320px] shrink-0';

const LiqKanbanCardResponsaveisModal = dynamic(
    () =>
        import('./LiqKanbanCardResponsaveisModal').then(
            (module) => module.LiqKanbanCardResponsaveisModal,
        ),
    { ssr: false },
);

type TSubstatusKanbanViewModel = ReturnType<typeof useViewModelSubstatusKanban>;

interface ILiquidacaoSubstatusKanbanLiveIndicatorProps {
    isConnected: boolean;
}

function LiquidacaoSubstatusKanbanLiveIndicator({
    isConnected,
}: ILiquidacaoSubstatusKanbanLiveIndicatorProps) {
    return (
        <span
            className="font-satoshi inline-flex items-center gap-1.5 rounded-lg border px-2.5 py-1.5 text-[11px] font-medium"
            style={{
                borderColor: withAlpha(COLORS.border, 0.55),
                color: isConnected ? COLORS.textDim : COLORS.textMuted,
            }}
            title={isConnected ? 'Sincronização em tempo real ativa' : 'Reconectando ao quadro…'}
            data-testid="substatus-kanban-live-indicator"
        >
            <span
                className={cn('size-2 shrink-0 rounded-full', isConnected && 'animate-pulse')}
                style={{
                    background: isConnected ? COLORS.success : withAlpha(COLORS.textMuted, 0.5),
                }}
                aria-hidden
            />
            {isConnected ? 'Ao vivo' : 'Reconectando…'}
        </span>
    );
}

interface ILiquidacaoSubstatusKanbanPresenceBarProps {
    viewers: LiquidacaoBoardViewer[];
    currentUserId?: string | null;
}

function LiquidacaoSubstatusKanbanPresenceBar({
    viewers,
    currentUserId,
}: ILiquidacaoSubstatusKanbanPresenceBarProps) {
    if (viewers.length === 0) return null;

    return (
        <div
            className="flex items-center gap-2.5 overflow-visible rounded-lg border px-2.5 py-1.5"
            style={{
                borderColor: withAlpha(COLORS.border, 0.55),
                background: withAlpha(COLORS.brand, 0.04),
            }}
            data-testid="substatus-kanban-presence-bar"
        >
            <Users className="size-3.5 shrink-0" style={{ color: COLORS.textDim }} />
            <span className="font-satoshi text-[11px]" style={{ color: COLORS.textDim }}>
                {viewers.length} vendo o quadro
            </span>
            <PresenceAvatarStack
                size={26}
                maxVisible={5}
                overflowTitle="Mais pessoas vendo o quadro"
                people={viewers.map((viewer) => ({
                    id: viewer.user_id,
                    name: viewer.display_name || viewer.username,
                    username: viewer.username,
                    avatarUrl: viewer.profile_picture,
                    isSelf: Boolean(
                        currentUserId && String(viewer.user_id) === String(currentUserId),
                    ),
                }))}
            />
        </div>
    );
}

interface ILiquidacaoSubstatusKanbanBoardHeaderProps {
    boardTotalLabel: string;
    isFetching: boolean;
    isConnected: boolean;
    viewers: LiquidacaoBoardViewer[];
    currentUserId?: string | null;
    onRefetch: () => void;
}

function LiquidacaoSubstatusKanbanBoardHeader({
    boardTotalLabel,
    isFetching,
    isConnected,
    viewers,
    currentUserId,
    onRefetch,
}: ILiquidacaoSubstatusKanbanBoardHeaderProps) {
    return (
        <div
            className="flex min-w-0 flex-wrap items-center justify-between gap-3"
            data-testid="substatus-kanban-board-header"
        >
            <p className="font-satoshi min-w-0 flex-1 text-xs" style={{ color: COLORS.textDim }}>
                {boardTotalLabel}
            </p>
            <div className="flex shrink-0 flex-wrap items-center gap-2">
                <LiquidacaoSubstatusKanbanLiveIndicator isConnected={isConnected} />
                <LiquidacaoSubstatusKanbanPresenceBar
                    viewers={viewers}
                    currentUserId={currentUserId}
                />
                <button
                    type="button"
                    onClick={onRefetch}
                    className="inline-flex cursor-pointer items-center gap-1.5 rounded-lg border px-2.5 py-1.5 text-xs font-semibold transition-colors hover:opacity-90"
                    style={{ borderColor: COLORS.border, color: COLORS.text }}
                >
                    <RefreshCw className={cn('size-3.5', isFetching && 'animate-spin')} />
                    Atualizar quadro
                </button>
            </div>
        </div>
    );
}

function buildSubstatusKanbanCardViewModel(
    card: ILiquidacaoCardKanban,
    columnId: string,
    handlers: TSubstatusKanbanViewModel['handlers'],
): ILiquidacaoSubstatusKanbanCardViewModel {
    return {
        credor: card.credor,
        tribunal: card.tribunal,
        valorLiquido: card.valor_liquido,
        priorityLevel: card.priority_level,
        priorityLevelDisplay: card.priority_level_display,
        pills: handlers.buildCardPills(card, columnId),
        substatusEnteredAt: handlers.resolveCardSubstatusEnteredAt(card),
        isSubstatusTempoUrgente: handlers.isCardSubstatusTempoUrgente(card),
        pendenciasCount: card.pendencias_count,
        cessionarios: handlers.getCardCessionarios(card),
        responsaveis: buildKanbanCardResponsaveisPresentation(card.responsaveis),
    };
}

interface ILiquidacaoSubstatusKanbanColumnProps {
    column: ISubstatusKanbanBoardColumnView;
    columnHeat: TSubstatusKanbanViewModel['ui']['columnHeatById'][string];
    handlers: TSubstatusKanbanViewModel['handlers'];
    updatingPriorityId: string | null;
    onOpenResponsaveisDetalhes: (snapshot: ILiqKanbanCardResponsaveisSnapshot) => void;
}

function LiquidacaoSubstatusKanbanColumn({
    column,
    columnHeat,
    handlers,
    updatingPriorityId,
    onOpenResponsaveisDetalhes,
}: ILiquidacaoSubstatusKanbanColumnProps) {
    const columnCount = column.cards.length;

    return (
        <div
            className={cn(
                SUBSTATUS_KANBAN_COLUMN_CLASS,
                'border-border/50 flex h-[min(72vh,640px)] flex-col overflow-hidden rounded-xl border bg-(--paper-surface) shadow-none',

