'use client';

import { CollaborationLiveIndicator } from '@/components/Collaboration/CollaborationLiveIndicator';
import { ResourcePresenceBar } from '@/components/Collaboration/ResourcePresenceBar';
import { useCollaborationContext } from '@/components/Collaboration/CollaborationContext';
import { useIsGerencialOficioDetail } from '@/app/crm/gerencial-broker/_hooks/useIsGerencialOficioDetail';
import { COLORS, withAlpha } from '@/app/crm/gerencial-broker/_constants/colors';
import { cn } from '@/lib/utils';

interface CollaborationPresenceStickyProps {
    label?: string;
}

export function CollaborationPresenceSticky({
    label = 'vendo esta página',
}: CollaborationPresenceStickyProps) {
    const collaboration = useCollaborationContext();
    const isGerencialOficioDetail = useIsGerencialOficioDetail();

    if (!collaboration) return null;

    return (
        <div className="pointer-events-none fixed right-4 top-[4.75rem] z-40 sm:top-20">
            <div
                className={cn(
                    'pointer-events-auto flex items-center gap-2 rounded-full px-2 py-1.5',
                    isGerencialOficioDetail
                        ? 'shadow-sm'
                        : 'border border-border/50 bg-background/95 shadow-md backdrop-blur-sm',
                )}
                style={
                    isGerencialOficioDetail
                        ? {
                              background: withAlpha(COLORS.card, 0.96),
                              border: `1px solid ${COLORS.border}`,
                          }
                        : undefined
                }
            >
                <CollaborationLiveIndicator isConnected={collaboration.isConnected} />
                {collaboration.displayViewers.length > 0 ? (
                    <ResourcePresenceBar
                        variant="compact"
                        viewers={collaboration.displayViewers}
                        currentUserId={collaboration.currentUserId}
                        label={label}
                        className="border-0 bg-transparent p-0 shadow-none"
                    />
                ) : null}
            </div>
        </div>
    );
}

/** @deprecated Use CollaborationPresenceSticky */
export const CollaborationLiveIndicatorSticky = CollaborationPresenceSticky;

