/**
 * @jest-environment jsdom
 */
import { afterAll, beforeEach, describe, expect, it, jest } from '@jest/globals';
import '@testing-library/jest-dom/jest-globals';
import { fireEvent, render, screen } from '@testing-library/react';
import type { ReactNode } from 'react';
import type { ILiquidacaoCardKanban } from '../interfaces/liquidacaoKanban';
import type { ISubstatusKanbanBoardColumnView } from '../ViewModels/useViewModelSubstatusKanban';

const mockRefetch = jest.fn();
const mockUseViewModel = jest.fn();

jest.mock('@/design-system', () => ({
    COLORS: {
        border: '#243044',
        text: '#12224a',
        textDim: '#94a3b8',
        textMuted: '#94a3b8',
        brand: '#2563eb',
        card: '#ffffff',
        success: '#16a34a',
    },
    withAlpha: (color: string) => color,
    OperationalLoadingPanel: ({ message }: { message: string }) => (
        <div data-testid="substatus-kanban-loading">{message}</div>
    ),
    OperationalEmptyState: ({ title }: { title: string }) => (
        <div data-testid="substatus-kanban-empty">{title}</div>
    ),
    PresenceAvatarStack: () => <div data-testid="presence-stack" />,
}));

jest.mock('@/components/Juridico/ColumnHeatSummary', () => ({
    ColumnHeatSummary: ({ summary }: { summary?: { total?: number } | null }) =>
        summary ? <div data-testid="column-heat-summary">heat</div> : null,
}));

jest.mock('@/app/crm/tarefas/_components/KanbanHorizontalScroll', () => ({
    KanbanHorizontalScroll: ({ children }: { children: ReactNode }) => (
        <div data-testid="kanban-horizontal-scroll">{children}</div>
    ),
}));

jest.mock('next/link', () => ({
    __esModule: true,
    default: ({
        href,
        children,
        ...props
    }: {
        href: string;
        children: ReactNode;
        'data-testid'?: string;
    }) => (
        <a href={href} {...props}>
            {children}
        </a>
    ),
}));

jest.mock('../Views/LiquidacaoScreen/LiquidacaoSubstatusKanbanCard', () => ({
    LiquidacaoSubstatusKanbanCard: ({
        viewModel,
        href,
        cardId,
    }: {
        viewModel: { credor: string };
        href: string;
        cardId: string;
    }) => (
        <a href={href} data-testid="liquidacao-substatus-kanban-card" data-card-id={cardId}>
            {viewModel.credor}
        </a>
    ),
}));

jest.mock('../ViewModels/useViewModelSubstatusKanban', () => ({
    useViewModelSubstatusKanban: (...args: unknown[]) => mockUseViewModel(...args),
}));

function makeCard(overrides: Partial<ILiquidacaoCardKanban> = {}): ILiquidacaoCardKanban {
    return {
        id: 'due-1',
        credor: 'Credor Teste',
        valor_liquido: 100000,
        status_liquidacao: null,
        sub_status: 'revisar_card_investimento',
        sub_status_display: 'Revisar Card de Investimento',
        responsaveis: {
            due_ativo: null,
            situacao_processual: null,
            certidoes: null,
        },
        tribunal: 'TRF1',
        prazo_fatal_liquidacao: '2026-10-01',
        fases_historico: [],
        sub_status_historico_fases: [],
        cessionarios_vinculados: [],
        priority_level: null,

