import { afterEach, beforeEach, describe, expect, it, jest } from '@jest/globals';
import '@testing-library/jest-dom/jest-globals';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { render, waitFor } from '@testing-library/react';
import type { ReactNode } from 'react';
import { QueryKeys } from '@/constants/query-keys';
import type { ILiquidacaoCardKanban, TSubstatusKanbanBoardResponse } from '../interfaces/liquidacaoKanban';

const sharedFilters = [{ id: 'priority_level', label: 'Prioridade', value: 'alta' }];
const listQueryFingerprint = '{"liquidacaoFase":"TODOS","priority_level":"alta"}';

const mockGetBoard = jest.fn<(filters?: unknown[]) => Promise<TSubstatusKanbanBoardResponse>>();

jest.mock('../hooks/useOperationalListFilterQueryState', () => ({
    useOperationalListFilterQueryState: () => ({
        liquidacaoListApiFilters: sharedFilters,
        listQueryFingerprint,
    }),
}));

jest.mock('../services/SubstatusKanbanService', () => ({
    substatusKanbanService: {
        getBoard: (...args: unknown[]) => mockGetBoard(...args),
        moveCard: jest.fn(async () => undefined),
    },
}));

jest.mock('@/hooks/useLiquidacaoBoardCollaboration', () => ({
    useLiquidacaoBoardCollaboration: () => ({
        acquireCardLock: jest.fn(async () => ({ ok: true, lock: null })),
        releaseCardLock: jest.fn(),
        isConnected: true,
    }),
}));

jest.mock('@/store/userInfo', () => ({
    useUserInfoStore: (
        selector: (state: { data: { username: string; user: string; user_id: string } }) => unknown,
    ) => selector({ data: { username: 'analista', user: 'analista', user_id: 'user-1' } }),
}));

jest.mock('@/components/Collaboration/use-collaboration-user', () => ({
    useCollaborationCurrentUserId: () => 'user-1',
    useCollaborationUserProfile: () => ({
        userId: 'user-1',
        username: 'analista',
        displayName: 'Analista',
    }),
}));

jest.mock('@/components/Collaboration/collaboration-user', () => ({
    resolveCollaborationViewers: (viewers: unknown[]) => viewers,
}));

jest.mock('@/functions/messages/toastMessage', () => ({
    sendToastMessage: jest.fn(),
}));

jest.mock('@/design-system', () => ({
    COLORS: {
        border: '#243044',
        text: '#12224a',
        textDim: '#94a3b8',
        textMuted: '#94a3b8',
        brand: '#2563eb',
        card: '#ffffff',
        success: '#16a34a',
    },
    withAlpha: (color: string) => color,
    OperationalLoadingPanel: ({ message }: { message: string }) => (
        <div data-testid="substatus-kanban-loading">{message}</div>
    ),
    OperationalEmptyState: ({ title }: { title: string }) => (
        <div data-testid="substatus-kanban-empty">{title}</div>
    ),
    PresenceAvatarStack: () => <div data-testid="presence-stack" />,
}));

jest.mock('@/components/Juridico/ColumnHeatSummary', () => ({
    ColumnHeatSummary: () => null,
}));

jest.mock('@/app/crm/tarefas/_components/KanbanHorizontalScroll', () => ({
    KanbanHorizontalScroll: ({ children }: { children: ReactNode }) => <div>{children}</div>,
}));

jest.mock('next/link', () => ({
    __esModule: true,
    default: ({ href, children }: { href: string; children: ReactNode }) => (
        <a href={href}>{children}</a>
    ),
}));

jest.mock('../Views/LiquidacaoScreen/LiquidacaoSubstatusKanbanCard', () => ({
    LiquidacaoSubstatusKanbanCard: () => null,
}));

