        expect(screen.getByTestId('liquidacao-substatus-kanban-view')).toBeInTheDocument();
        expect(screen.getByText('1 operação no quadro', { exact: false })).toBeInTheDocument();
        expect(screen.getByText('clique no card', { exact: false })).toBeInTheDocument();
        expect(screen.queryByText('arraste', { exact: false })).not.toBeInTheDocument();
