        expect(screen.getByRole('button', { name: 'Atualizar quadro' })).toBeInTheDocument();
        expect(screen.getByTestId('substatus-kanban-column-revisao')).toHaveTextContent('Revisão');
        expect(screen.getByTestId('substatus-kanban-column-count-revisao')).toHaveTextContent('1');
