        expect(screen.getByTestId('substatus-kanban-column-empty-investidor')).toHaveTextContent(
            'Nenhuma operação nesta coluna',
        );
        expect(screen.queryByTestId('liquidacao-cards-view')).not.toBeInTheDocument();
    });

    it('renderiza link para a liquidação dedicada no card', async () => {
        await renderView();

        const cardLink = screen.getByTestId('liquidacao-substatus-kanban-card');
        expect(cardLink).toHaveAttribute('href', '/juridico/due-diligence-2.0/due-1/liquidacao');
        expect(cardLink).toHaveAttribute('data-card-id', 'due-1');
    });

    it('dispara refetch ao atualizar o quadro', async () => {
        await renderView();

        fireEvent.click(screen.getByRole('button', { name: 'Atualizar quadro' }));

        expect(mockRefetch).toHaveBeenCalledTimes(1);
    });

    it('mostra presença quando há viewers no quadro', async () => {
        mockUseViewModel.mockReturnValue(
            createViewModel({
                ui: {
                    viewers: [
                        {
                            user_id: 'user-1',
