                        },
                        {
                            user_id: 'user-2',
                            username: 'bruno',
                            display_name: 'Bruno Lima',
                        },
                    ],
                },
            }),
        );

        await renderView();

        expect(screen.getByTestId('substatus-kanban-presence-bar')).toHaveTextContent(
            '2 vendo o quadro',
        );
        expect(screen.getByTestId('presence-stack')).toBeInTheDocument();
    });
});

