const BrokerSlider = lazy(() => import('@/components/Sliders/BrokerSlider'));
const DocumentsSection = lazy(() =>
    import('@/app/crm/broker/[id]/_components/DocumentsSection').then((module) => ({ default: module.DocumentsSection })),
);
const ReadOnlyOficioInfoForm = lazy(() =>
    import('@/components/Forms/ReadOnlyOficioInfoForm').then((module) => ({
        default: module.ReadOnlyOficioInfoForm,
    })),
);
const NewEditOficioBrokerForm = lazy(() => import('@/components/Forms/NewEditOficioBrokerForm'));

export const BrokerOficioDetails = ({ id }: { id: string }) => {
    const isGerencialOficioDetail = useIsGerencialOficioDetail();
    const sectionFallback = isGerencialOficioDetail ? (
        <GerencialOficioSectionSkeleton />
    ) : (
        <div className="col-span-12 flex justify-center py-8">
            <LoaderCircle className="animate-spin text-primary" />
        </div>
    );

    /**
     * ==========>> STORE CONSTS <<==========
     */
    const isCoordenadorOrMaster = useBrokerStore((store) => store.isCoordenadorOrMaster);
    const setIsCoordenadorOrMaster = useBrokerStore((store) => store.setIsCoordenadorOrMaster);
    const userRole = useUserInfoStore((store) => store.data.role);
    const setExtratoId = useBrokerStore((store) => store.setExtratoId);

    // ==============
    // # Data Hooks
    // ==============
    // useQuery (não suspense): 404/403 precisam renderizar UI local — useSuspenseQuery
    // lança no error boundary e ignora o tratamento abaixo.
    const {
        data: detailedExtratoData,
        isError: isErrorExtratoData,
        error: extratoDataError,
