export function LiquidacaoSubstatusKanbanView() {
    const { ui, handlers, constants } = useViewModelSubstatusKanban({
        service: substatusKanbanService,
    });
    const isResponsaveisModalOpen = useDueDiligenceStore(
        (state) => state.isLiqKanbanCardResponsaveisModalOpen,
    );
    const responsaveisSnapshot = useDueDiligenceStore(
        (state) => state.liqKanbanCardResponsaveisSnapshot,
    );
    const showResponsaveisModal = useDueDiligenceStore(
        (state) => state.showLiqKanbanCardReponsaveisModal,
    );
    const closeResponsaveisModal = useDueDiligenceStore(
        (state) => state.closeLiqKanbanCardResponsaveisModal,
    );

    if (ui.isLoading) {
        return (
            <OperationalLoadingPanel minHeight="480px" message="Montando quadro de liquidação…" />
        );
    }

    return (
        <div className="min-w-0 space-y-3" data-testid="liquidacao-substatus-kanban-view">
            <LiquidacaoSubstatusKanbanBoardHeader
                boardTotalLabel={constants.boardTotalLabel}
                isFetching={ui.isFetching}
                isConnected={ui.isConnected}
                viewers={ui.viewers}
                currentUserId={ui.currentUserId}
                onRefetch={() => {
                    handlers.refetch();
                }}
            />

            {ui.isEmpty ? (
                <div
                    className="overflow-hidden rounded-2xl border"
                    style={{ borderColor: COLORS.border, background: COLORS.card }}
                >
                    <OperationalEmptyState
                        icon={LayoutGrid}
                        title="Nenhuma operação no quadro"
                        description="Ajuste os filtros ou aguarde novas diligências entrarem em liquidação."
                        className="min-h-64"
                    />
                </div>
            ) : (
                <KanbanHorizontalScroll>
                    <div
                        className="grid min-h-120 auto-cols-80 grid-flow-col gap-3 pb-2"
                        data-testid="substatus-kanban-board-grid"
                    >
                        {ui.boardColumns.map((column) => (
                            <LiquidacaoSubstatusKanbanColumn
                                key={column.id}
                                column={column}
                                columnHeat={ui.columnHeatById[column.id]}
                                handlers={handlers}
                                updatingPriorityId={ui.updatingPriorityId}
                                onOpenResponsaveisDetalhes={showResponsaveisModal}
                            />
                        ))}
                    </div>
                </KanbanHorizontalScroll>
            )}

            {isResponsaveisModalOpen ? (
                <LiqKanbanCardResponsaveisModal
                    isOpen={isResponsaveisModalOpen}
                    snapshot={responsaveisSnapshot}
                    onOpenChange={(isOpen) => {
                        if (!isOpen) closeResponsaveisModal();
                    }}
                />
            ) : null}
        </div>
    );
}
